MagickBooleanType WritePSDImageChannels(const PSDInfo *psd_info,
                                        const ImageInfo *image_info,
                                        Image *image, Image *next_image,
                                        MagickBooleanType separate,
                                        ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t scene = 0;
  Image *images = image;

  for ( ; images != (Image *) NULL; images = GetNextImageInList(images))
  {
    if (images->columns == 0 || images->rows == 0)
      continue;

    if (next_image != (Image *) NULL)
    {
      if (next_image->compression == RLECompression)
        status &= WritePSDChannelRLECompression(psd_info, image_info, images,
                                                next_image, separate, exception);
      else
        status &= WritePSDChannelNoCompression(psd_info, image_info, images,
                                               next_image, separate, exception);
    }

    if (!images->alpha_trait)
      status &= WritePSDNonAlphaChannel(psd_info, image_info, images,
                                        next_image, separate, exception);
    else
      status &= WritePSDAlphaChannel(psd_info, image_info, images, next_image,
                                     separate, exception);

    if (separate != MagickFalse)
    {
      for (int channel = 0; channel < psd_info->channel_count; channel++)
        status &= WritePSDSpecificChannel(psd_info, image_info, images,
                                          next_image, channel, exception);
    }

    if (image_info->debug != MagickFalse)
      (void) fprintf(stderr, "Wrote %zu/%zu channels successfully.\n",
                     image_info->debug_count, psd_info->channel_count);

    scene++;
  }

  return status;
}

MagickBooleanType WritePSDImageChannels(const PSDInfo *psd_info,
                                        const ImageInfo *image_info,
                                        Image *image, Image *next_image,
                                        MagickBooleanType separate,
                                        ExceptionInfo *exception) {
  size_t width, height;
  unsigned char *pixel_data = NULL;
  size_t channel_count = 0;
  CompressionType compression = psd_info->compression;
  ColorSpace color_space = image->colorspace;
  MagickBooleanType status = MagickTrue;
  size_t x, y;

  width = image->columns;
  height = image->rows;

  pixel_data = (unsigned char *) AcquireMemory(width * height * sizeof(*pixel_data));
  if (pixel_data == (unsigned char *) NULL) {
    ThrowPSDException(ResourceLimitError, UnableToAcquireMemory, image->filename);
    return MagickFalse;
  }

  if (compression == RLECompression)
    pixel_data = ApplyPackbitsCompression(pixel_data, width * height);

  switch (color_space) {
    case GrayColorspace:
      channel_count = 1;
      break;
    case IndexColorspace:
      channel_count = 1;
      break;
    case RGBColorspace:
      channel_count = 3;
      break;
    default:
      channel_count = 3;
  }

  if (image->alpha_trait)
    channel_count++;

  for (y = 0; y < height; y++) {
    for (x = 0; x < width; x++) {
      PixelIndex index = 0;
      PixelInfo pixel;

      GetPixelInfo(image, &pixel);
      GetPixelInfoRGB(image, x, y, &pixel);

      switch (color_space) {
        case GrayColorspace:
          pixel_data[y * width + x] = ClampToQuantum(pixel.red);
          break;
        case IndexColorspace:
          index = pixel.red / MaxColormapValue;
          pixel_data[y * width + x] = (unsigned char) index;
          break;
        case RGBColorspace:
          pixel_data[y * width + x * 3 + 0] = ClampToQuantum(pixel.red);
          pixel_data[y * width + x * 3 + 1] = ClampToQuantum(pixel.green);
          pixel_data[y * width + x * 3 + 2] = ClampToQuantum(pixel.blue);
          break;
        default:
          pixel_data[y * width + x * 3 + 0] = ClampToQuantum(pixel.red);
          pixel_data[y * width + x * 3 + 1] = ClampToQuantum(pixel.green);
          pixel_data[y * width + x * 3 + 2] = ClampToQuantum(pixel.blue);
      }

      if (image->alpha_trait)
        pixel_data[y * width + x * 4 + 3] = ClampToQuantum(pixel.opacity);
    }

    if (y % 100 == 0)
      ProgressMonitor(WriteImageTag, y, height);
  }

  if (WriteImagePixelData(psd_info, image_info, image, pixel_data, channel_count, exception) == MagickFalse)
    status = MagickFalse;

  pixel_data = RelinquishMemory(pixel_data);

  return status;
}

MagickBooleanType WritePSDImageChannels(const PSDInfo *psd_info, const ImageInfo *image_info, Image *image, Image *next_image, MagickBooleanType separate, ExceptionInfo *exception) {
  MagickBooleanType status = MagickTrue;
  size_t number_pixels = 0;
  Quantum *pixels = NULL;

  if (image == (Image *) NULL)
    return MagickFalse;

  number_pixels = image->columns * image->rows;

  pixels = (Quantum *) AcquireQuantumMemory(number_pixels, sizeof(*pixels));
  if (pixels == (Quantum *) NULL)
    return MagickFalse;

  switch (image->compression) {
    case RLECompression:
      status = ApplyPackbitsCompression(pixels, image->data, number_pixels);
      if (status == MagickFalse) {
        RelinquishMemory(pixels);
        return status;
      }
      break;
    default:
      break;
  }

  switch (image->colorspace) {
    case GrayColorspace:
      status = WriteGrayscalePixels(pixels, image->alpha_trait, image, exception);
      break;
    case RGBColorspace:
      status = WriteRGBPixels(pixels, image->alpha_trait, image, exception);
      break;
    case CMYKColorspace:
      status = WriteCMYKPixels(pixels, image->alpha_trait, image, exception);
      break;
    default:
      break;
  }

  if (separate) {
    status = WriteAlphaChannel(pixels, image->alpha_trait, image, exception);
  }

  if (progress_monitor != (MagickProgressMonitor) NULL)
    progress_monitor("Writing PSD Channels", 1, 1, exception->client_data);

  RelinquishMemory(pixels);
  return status;
}

